"""Draft-vocabulary records pin both generated bytes and generation inputs."""

import json
import tempfile
import unittest
from pathlib import Path
from unittest.mock import patch

from dev.tools.draft_vocabulary_manifest import digest, write_manifest


class DraftVocabularyManifestTest(unittest.TestCase):
    def test_records_exact_inputs_and_invocation(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            corpus = root / "corpus"
            corpus.mkdir()
            tokenizer = root / "tokenizer.json"
            source = root / "source.cpp"
            bitmap = root / "bitmap.cpp"
            manifest = root / "manifest.json"
            for path in (tokenizer, source, bitmap, corpus / "sample.parquet"):
                path.write_bytes(path.name.encode())
            command = ["python", "generator.py", "--code", "path with spaces"]
            with patch(
                "dev.tools.draft_vocabulary_manifest.importlib.metadata.version",
                return_value="pinned",
            ):
                write_manifest(manifest, tokenizer, corpus, [source], bitmap, command)
                first = json.loads(manifest.read_text())
                self.assertEqual(first["generated_cpp_sha256"], digest(bitmap))
                self.assertEqual(
                    first["inputs"]["tokenizer"]["sha256"], digest(tokenizer)
                )
                self.assertIn("'path with spaces'", first["invocation"])
                source.write_text("changed input")
                write_manifest(manifest, tokenizer, corpus, [source], bitmap, command)
            second = json.loads(manifest.read_text())
            self.assertNotEqual(
                first["input_identity_sha256"], second["input_identity_sha256"]
            )

    def test_checked_in_bitmap_matches_legacy_record(self):
        root = Path(__file__).resolve().parents[3]
        cpp = root / "runtime/model/Qwen4DraftVocabularyData.cpp"
        record = json.loads(cpp.with_suffix(".manifest.json").read_text())
        self.assertEqual(record["generated_cpp_sha256"], digest(cpp))
        self.assertIsNone(record["exact_invocation"])
